// This code has been fully generated by an AI.

package store

import (
	"context"
	"errors"
	"testing"
)

func TestAttachSourceAndTitles(t *testing.T) {
	ctx := context.Background()
	s := newStore(t)
	ids := seed(t, s, item{"cycling", "2026-10-01 10:00"}, item{"cycling", "2026-10-02 10:00"})

	if err := s.AttachSource(ctx, ids[0], "garmin", "24564314266", "Burghausen Radfahren"); err != nil {
		t.Fatal(err)
	}
	if a, _ := s.Get(ctx, ids[0]); a.Name != "Burghausen Radfahren" {
		t.Errorf("title not applied: %q", a.Name)
	}
	keys, err := s.SourceKeys(ctx, "garmin")
	if err != nil || len(keys) != 1 || keys[0] != "24564314266" {
		t.Errorf("keys %v %v", keys, err)
	}

	// Renamed in Garmin Connect → follows, because the user did not rename it here.
	if changed, err := s.SetSourceTitle(ctx, "garmin", "24564314266", "Feierabend Gravel"); err != nil || !changed {
		t.Errorf("rename at source: %v %v", changed, err)
	}
	if a, _ := s.Get(ctx, ids[0]); a.Name != "Feierabend Gravel" {
		t.Errorf("name %q", a.Name)
	}

	// Renamed in my Velo → Garmin titles no longer overwrite it.
	if err := s.Rename(ctx, ids[0], "Meine Runde"); err != nil {
		t.Fatal(err)
	}
	if changed, _ := s.SetSourceTitle(ctx, "garmin", "24564314266", "Noch ein Garmin-Name"); changed {
		t.Error("user name must win")
	}
	if a, _ := s.Get(ctx, ids[0]); a.Name != "Meine Runde" {
		t.Errorf("name %q", a.Name)
	}

	// Attaching again is idempotent; a re-link moves the key.
	if err := s.AttachSource(ctx, ids[1], "garmin", "24564314266", ""); err != nil {
		t.Fatal(err)
	}
	if keys, _ := s.SourceKeys(ctx, "garmin"); len(keys) != 1 {
		t.Errorf("duplicate key: %v", keys)
	}
	if _, err := s.SetSourceTitle(ctx, "garmin", "unknown", "x"); !errors.Is(err, ErrNotFound) {
		t.Errorf("unknown key: %v", err)
	}
}
